const posts = $input.all();
const results = [];
for (const item of posts) {
  const d = item.json;
  if (!d["Post link"] && !d["Post ID"]) continue;
  const postLink = d["Post link"] || "";
  const m = postLink.match(/\/p\/([^\/]+)\//);
  const shortcode = m ? m[1] : null;
  const postId = String(d["Post ID"] || "").trim();
  if (!postId) continue;
  const rawDate = String(d["Post date"] || "");
  if (rawDate.length !== 8) continue;
  const fecha = rawDate.slice(0,4)+"-"+rawDate.slice(4,6)+"-"+rawDate.slice(6,8);
  const postType = d["Post type"] || "";
  let tipo = "feed";
  if (postType === "CAROUSEL_ALBUM") tipo = "carousel";
  else if (postType === "VIDEO") tipo = "reel";
  results.push({ json: {
    upsert_key: postId,
    post_shortcode: shortcode, post_url: postLink,
    image_url: d["Post image URL"] || null,
    meta_post_id: postId,
    plataforma: "instagram", tipo, fecha_publicacion: fecha,
    caption: (d["Post caption"] || "").substring(0, 3000),
    alcance: Math.round(Number(d["Post reach"]) || 0),
    impresiones: Math.round(Number(d["Post impressions"]) || 0),
    likes: Math.round(Number(d["Post likes"]) || 0),
    comentarios: Math.round(Number(d["Post comments count"]) || 0),
    guardados: Math.round(Number(d["Post saves"]) || 0),
    engagement_rate: Number(d["Post engagement rate"]) || 0,
    compartidos: 0, visualizaciones: 0
  }});
}
return results;

const reels = $input.all();
const seen = new Map();
for (const item of reels) {
  const d = item.json;
  const postId = String(d["Post ID"] || "").trim();
  if (!postId) continue;
  const rawDate = String(d["Post date"] || "");
  if (rawDate.length !== 8) continue;
  const fecha = rawDate.slice(0,4)+"-"+rawDate.slice(4,6)+"-"+rawDate.slice(6,8);
  const existing = seen.get(postId);
  const likes = Math.round(Number(d["Reels likes"]) || 0);
  if (existing && existing.likes >= likes) continue;
  seen.set(postId, {
    upsert_key: postId,
    post_shortcode: null, post_url: null,
    meta_post_id: postId,
    plataforma: "instagram", tipo: "reel", fecha_publicacion: fecha,
    caption: (d["Post caption"] || "").substring(0, 3000),
    alcance: 0, impresiones: 0, likes,
    comentarios: Math.round(Number(d["Reels comments"]) || 0),
    guardados: 0, engagement_rate: 0,
    compartidos: Math.round(Number(d["Reels shares"]) || 0),
    visualizaciones: Math.round(Number(d["Reels plays"]) || 0)
  });
}
return Array.from(seen.values()).map(json => ({ json }));

const items = $input.all();
const SCHEMA = ["upsert_key","post_shortcode","post_url","image_url","meta_post_id",
  "plataforma","tipo","fecha_publicacion","caption","alcance","impresiones","likes",
  "comentarios","guardados","engagement_rate","compartidos","visualizaciones"];
const normalized = items.map(it => {
  const out = {};
  for (const k of SCHEMA) out[k] = it.json[k] !== undefined ? it.json[k] : null;
  return out;
});
const batchSize = 50;
const batches = [];
for (let i = 0; i < normalized.length; i += batchSize) {
  batches.push({ json: { batch: normalized.slice(i, i + batchSize) }});
}
return batches;
